lessons.example_code:
h1 {
  color: blue;
}

body {
  background-color: #f5f5f5;
}
p {
  color: #333;
}

h1 {
  font-size: 32px;
  font-weight: bold;
}
p {
  font-family: sans-serif;
}

.card {
  margin: 20px;
  padding: 15px;
  border: 1px solid black;
}

.box {
  border: 2px solid black;
  border-radius: 10px;
}

p { color: grey; }
.btn { color: white; }
#main-title { font-size: 50px; }

.container {
  display: flex;
  justify-content: center;
  align-items: center;
}

.grid-container {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
}

button {
  background: grey;
}
button:hover {
  background: blue;
}

button {
  background: grey;
  transition: 0.3s;
}
button:hover {
  background: blue;
}

header {
  background: #2563eb;
  color: white;
  display: flex;
  justify-content: space-between;
  padding: 20px;
}

nav a {
  color: white;
  text-decoration: none;
  margin-right: 15px;
  font-weight: 600;
}

img {
  width: 100%;
  max-width: 300px;
  border-radius: 10px;
  box-shadow: 0 4px 6px rgba(0,0,0,0.1);
}

table {
  width: 100%;
  border-collapse: collapse;
}
th, td {
  padding: 12px;
  border: 1px solid #ddd;
  text-align: left;
}

input {
  width: 100%;
  padding: 12px;
  margin-bottom: 15px;
  border: 2px solid #ccc;
  border-radius: 8px;
}

button {
  background: #2563eb;
  color: white;
  padding: 10px 20px;
  border: none;
  cursor: pointer;
}
button:active {
  transform: scale(0.95);
}

.card {
  background: white;
  box-shadow: 0 4px 10px rgba(0,0,0,0.2);
}

h1 {
  text-shadow: 2px 2px 5px grey;
}

@media (max-width: 600px) {
  body {
    background: lightblue;
  }
}

.container {
  display: flex;
  flex-wrap: wrap;
}

/* --- Header Section --- */
.header-main { padding: 20px; }

/* --- Buttons --- */
.btn-primary { background: blue; }

:root {
  --main-color: #2563eb;
}
button {
  background: var(--main-color);
}

.header {
  position: sticky;
  top: 0;
  z-index: 100;
}

/* Import in HTML: <link ...> */
